/** Últimos n meses (incluido el actual), del más antiguo al más nuevo. */
export function lastMonths(n) {
  const out = [];
  const d = new Date();
  d.setDate(1);
  for (let i = n - 1; i >= 0; i--) {
    const c = new Date(d.getFullYear(), d.getMonth() - i, 1);
    out.push(`${c.getFullYear()}-${String(c.getMonth() + 1).padStart(2, "0")}`);
  }
  return out;
}

